// Builds a message from a Sonarr/Radarr webhook. Ignores upgrades and other events.
const b = $input.first().json.body || {};
const link = '\n\n▶️ https://jellyfin.tailc33d1b.ts.net';

if (b.eventType === 'Test') {
  return [{ json: { text: `✅ Test from ${b.instanceName || 'Sonarr/Radarr'} reached n8n` } }];
}
if (b.eventType !== 'Download' || b.isUpgrade) return [];

if (b.movie) {
  return [{ json: { text: `🎬 New movie on Jellyfin: ${b.movie.title} (${b.movie.year})` + link } }];
}
if (b.series) {
  const pad = (n) => String(n).padStart(2, '0');
  const eps = (b.episodes || [])
    .map(e => `S${pad(e.seasonNumber)}E${pad(e.episodeNumber)}${e.title ? ' – ' + e.title : ''}`)
    .join('\n');
  const plural = (b.episodes || []).length > 1 ? 's' : '';
  return [{ json: { text: `📺 New episode${plural} of ${b.series.title}:\n${eps}` + link } }];
}
return [];
